import { BookingService } from './booking.service';
import { BookingStatus } from './booking.entity';

describe('BookingService.cancelBooking', () => {
  it('sets status to CANCELLED', async () => {
    const service = new BookingService(
      { refund: async () => undefined } as any,
      { releaseSlot: async () => undefined } as any,
      { notifyOwner: async () => undefined } as any,
    );

    const booking = await service.cancelBooking('b1');
    expect(booking.status).toBe(BookingStatus.CANCELLED);
  });
});

@Post(':id/cancel')
  async cancel(@Param('id') id: string) {
    return this.bookingService.cancelBooking(id);
  }

export class Booking {
  constructor(
    public readonly id: string,
    public status: BookingStatus,
  ) {}

  get slotId(): string {
    return `slot-${this.id}`;
  }

  get ownerId(): string {
    return `owner-${this.id}`;
  }
}

async cancelBooking(bookingId: string): Promise<Booking> {
    const booking = new Booking(bookingId, BookingStatus.PAID);
    booking.status = BookingStatus.CANCELLED;

    await this.paymentService.refund(bookingId);
    await this.slotService.releaseSlot(booking.slotId);
    await this.notificationService.notifyOwner(booking.ownerId, bookingId);

    return booking;
  }

async notifyOwner(ownerId: string, bookingId: string): Promise<void> {
    return;
  }

export class PaymentTransaction {
  constructor(
    public readonly bookingId: string,
    public status: PaymentStatus,
  ) {}
}

async refund(bookingId: string): Promise<PaymentTransaction> {
    const transaction = new PaymentTransaction(bookingId, PaymentStatus.PAID);
    transaction.status = PaymentStatus.REFUNDED;
    return transaction;
  }
